' 2>/dev/null; perl -e '
use IPC::Open3; 
my (%up,%lo,@keep);
for my $b (1..255) {
  my $w = chr($b) x 2;
  my $pid = open(my $fh, "-|") or do { exec("/workspace/dataset/test11_executable","1",$w); die };
  local $/; my $out = <$fh>; close $fh;
  my @L = split /\n/, $out, -1;
  my $cap = $L[5];
  if (length($cap) != 2) { printf("ODD %02x len=%d [%s]\n",$b,length($cap),unpack("H*",$cap)); next; }
  my ($c0,$c1) = (ord(substr($cap,0,1)), ord(substr($cap,1,1)));
  $up{$b}=$c0 if $c0 != $b;
  $lo{$b}=$c1 if $c1 != $b;
  push @keep, sprintf("%02x=>[%s]",$b,$L[8]) if length($L[8]);
}
print "TOUPPER: ", join(" ", map { sprintf("%02x->%02x",$_,$up{$_}) } sort {$a<=>$b} keys %up), "\n\n";
print "TOLOWER: ", join(" ", map { sprintf("%02x->%02x",$_,$lo{$_}) } sort {$a<=>$b} keys %lo), "\n\n";
print "PARAM nonempty: ", join(" ", @keep), "\n";
'
